import {MISSIONS,aiMessage} from './progression.mjs';
import {weaponName} from './evolutions.mjs';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fieldIds=['industrial','mine','ecology'];
export class CampaignShell{
 constructor({run,profile,$,startMission,goBase,showDialog,closeDialog,openArchive,onSound,soundEnabled,onEquipmentTest,onDropMode}){Object.assign(this,{run,profile,$,startMission,goBase,showDialog,closeDialog,openArchive,onSound,soundEnabled,onEquipmentTest,onDropMode});this.quick=false;this.signature=''}
 refresh(){const {run:r,profile:p,$}=this;const sig=JSON.stringify([r.missionId,r.wave,r.sampleRecovered,p.data,r.state]);if(sig===this.signature)return;this.signature=sig;const m=MISSIONS[r.missionId]||MISSIONS.training;$('missionName').textContent=m.name;$('missionObjective').textContent=r.state==='menu'?'任务选择与长期档案':m.subtitle;$('assistantMessage').textContent=r.missionId==='core'&&r.wave>=9&&!r.sampleRecovered&&!p.data.trueEnding?'ERROR // 原始参照缺失':p.data.trueEnding?'你回来了。身份记录与通信已经恢复。':p.data.training&&p.aiStage===0?'外勤系统就绪。选择一项任务，我会记录你的装备反馈。':aiMessage(p.aiStage);$('assistantChannel').classList.toggle('signal-error',p.aiStage===3);$('assistantStage').textContent=['LINK / ONLINE','LINK / DELAYED','LINK / UNSTABLE','LINK / ERROR'][p.aiStage];$('missionName').style.color=m.color}
 renderBase(card){const {$,profile:p}=this,d=p.data;card.innerHTML=`<div class="base-shell"><div class="base-top"><a class="base-brand" href="#" id="baseBrand">V<span>•</span> <b>VALENCE<small>链式反应 · 任务档案</small></b></a><div class="base-tools"><button id="baseSound" class="base-tool">${this.soundEnabled()?'♫ 音效开启':'♫ 音效静音'}</button><button id="baseArchive" class="base-tool">▤ 档案 ${d.clues.length}</button><button id="manageSave" class="base-tool">存档</button></div></div><div class="base-intro"><div><div class="eyebrow">${d.training?'FIELD OPERATIONS / 外勤控制台':'EQUIPMENT VALIDATION / 设备测试'}</div><h2>${d.training?'选择下一次<span>行动。</span>':'一场实验。<br>从<span>普通枪</span>开始。'}</h2><p>${d.training?'每项任务十关。任务完成后带回特别物件，失败保留已归档的发现。':'测试新型装备，在十关生存中收集物质、组合双枪。通过测试后获得外勤资格。'}</p></div><div class="base-signal ${p.aiStage===3?'signal-error':''}"><div><i></i> 实验助理 VELA <span>${['在线','响应延迟','通信不稳定','ERROR'][p.aiStage]}</span></div><p>${esc(d.trueEnding?'你回来了。通信已恢复，所有任务记录已经归档。':d.training&&p.aiStage===0?'外勤资格已确认。选择任务后，我们继续。':aiMessage(p.aiStage))}</p><small>${d.trueEnding?'CHANNEL RESTORED / 你回来了':`SESSION ${String(d.attempts+1).padStart(3,'0')} · ${p.storageAvailable?'本地档案自动保存':'临时档案 · 建议导出备份'}`}</small></div></div>${d.training?`<div class="task-mode"><div><b>任务时长</b><small>战斗、改装和首领规则完整保留</small></div><button id="quickMode" class="${this.quick?'active':''}">加速试玩 · 约2分钟/图</button><button id="normalMode" class="${!this.quick?'active':''}">标准 · 约10分钟/图</button></div>`:`<div class="training-actions"><button id="startQuick" class="primary">开始快速装备测试 <span>↗</span></button><button id="start" class="base-secondary">标准装备测试 · 约10分钟</button><p>快速模式缩短每关时间，并降低敌人生命和伤害，适合先体验完整故事流程。</p></div>`}<div class="task-grid">${fieldIds.map((id,i)=>{const m=MISSIONS[id],done=d.relics.includes(m.relic.id);return `<button class="task-card task-${id} ${done?'task-complete':''}" id="mission-${id}" ${!d.training?'disabled':''}><div class="task-art art-${id}"><span>${['⌁','◇','◌'][i]}</span><i></i><i></i><i></i></div><div class="task-copy"><div class="task-number">0${i+1} / ${done?'回收已归档':d.training?'外勤任务':'完成测试后开放'}</div><h3>${m.name}</h3><p>${m.description}</p><div class="task-bottom"><span>${done?'✓ '+m.relic.name:'待回收物件'}</span><b>${d.training?'任务简报 ↗':'锁定'}</b></div></div></button>`}).join('')}${p.keyReady?`<button id="mission-core" class="task-card task-core"><div class="task-art art-core"><span>⌘</span><i></i><i></i><i></i></div><div class="task-copy"><div class="task-number">04 / MAINTENANCE ACCESS</div><h3>微观核心</h3><p>维护钥匙已回应。追踪失联信号，进入封闭结构内部。</p><div class="task-bottom"><span>◆ 维护钥匙已组合</span><b>访问入口 ↗</b></div></div></button>`:''}</div><div class="base-bottom"><div><span class="micro">RECOVERED OBJECTS / 已归档物件</span><div class="relic-case">${fieldIds.map(id=>{const m=MISSIONS[id],has=d.relics.includes(m.relic.id);return `<span class="${has?'relic-owned':''}"><i>${has?'◆':'◇'}</i>${has?m.relic.name:'待归档'}</span>`}).join('')}</div></div><div class="base-fineprint">${p.keyReady?'访问条件已满足。维护程序已载入新任务。':'完整装备与能力在每次任务中重新构筑。'}<br>钻石、物质、血瓶需亲自拾取；枪、配件、枪口关末收取。</div></div><div class="base-footer"><span>LOCAL V5.2 / ${p.storageAvailable?'进度保存在当前浏览器':'当前环境限制持久存储，请使用存档导出'}</span><div>${d.training?'<button id="start" class="text-button">重做装备测试</button>':''}<button id="equipmentTest" class="text-button">装备试验</button><button id="dropMode" class="text-button">物质掉率：${this.run.dropMode==='high'?'试玩加量75%':'标准18%'}</button></div></div></div>`;
 $('equipmentTest').onclick=this.onEquipmentTest;$('dropMode').onclick=this.onDropMode;$('baseBrand').onclick=e=>e?.preventDefault?.();$('baseArchive').onclick=this.openArchive;$('manageSave').onclick=()=>this.openSave();$('baseSound').onclick=()=>{this.onSound();this.renderBase(card)};
 if(!d.training)$('startQuick').onclick=()=>{this.quick=true;this.startMission('training',true)};
 $('start').onclick=()=>this.startMission('training',d.training?this.quick:false);
 if(d.training){$('quickMode').onclick=()=>{this.quick=true;this.renderBase(card)};$('normalMode').onclick=()=>{this.quick=false;this.renderBase(card)}}
 for(const id of [...fieldIds,...(p.keyReady?['core']:[])])$('mission-'+id).onclick=()=>{if(p.unlocked(id))this.briefing(id)};
 }
 briefing(id){const m=MISSIONS[id];this.showDialog('briefing',`<div class="eyebrow">MISSION BRIEF / 任务简报</div><h2>${m.name}</h2><p>${m.description}</p><div class="brief-facts"><span>十关生存</span><span>${this.quick?'加速试玩 · 约2分钟':'标准 · 约10分钟'}</span><span>普通枪出发</span></div><p>${id==='core'?'本地维护程序已接管导航。访问钥匙有效。':'完成任务并成功返回基地后，特别物件才会永久归档。'}</p><p class="brief-channel">实验助理：${esc(aiMessage(this.profile.aiStage))}</p><button id="deployMission" class="primary wide">确认出发 <span>↗</span></button><button id="cancelBrief" class="back-link">返回任务面板</button>`);this.$('deployMission').onclick=()=>{this.closeDialog(false);this.startMission(id,this.quick)};this.$('cancelBrief').onclick=()=>this.closeDialog()}
 archiveHtml(){const d=this.profile.data;return `<div class="eyebrow">PERSISTENT ARCHIVE / 长期档案</div><h2>已经发现的，<span>不会遗忘。</span></h2><p>记录可跨任务查看。特别物件须完成任务后带回。</p>${fieldIds.map(id=>{const m=MISSIONS[id],known=d.clues.includes(m.clue.id),owned=d.relics.includes(m.relic.id);return `<div class="archive-record"><span>${m.name}</span><h3>${known?m.clue.title:'记录尚未恢复'}</h3><p>${known?m.clue.text:'继续完成任务，可能找回这一区域的维护记录。'}</p>${owned?`<small>◆ 已归档：${m.relic.name} · ${m.relic.description}</small>`:''}</div>`}).join('')}${d.trueEnding?'<div class="archive-record restored-record"><h3>通信已恢复</h3><p>“你回来了。”</p><p>恢复的任务头标记着“核心隔离修复”。侵染破坏了任务记录，把各区域的目标改写成常规回收；实验助理与玩家都无法读到完整目的。保存完整的隔离结构让身份记录与通信得到恢复。</p><small>这是本版demo补全的故事解释。</small></div>':''}<p class="abstract-note">这些侵染特征来自本故事中的设施与样本，不能作为现实材料的一般规律。</p><button id="closeArchive" class="primary wide">返回${this.run.state==='paused'?'现场':'基地'}</button>`}
 openSave(){this.showDialog('save',`<div class="eyebrow">LOCAL ARCHIVE / 存档管理</div><h2>带走你的<span>发现。</span></h2><p>导出文本可备份长期档案。不同文件、浏览器或设备的本地存储可能不互通。</p><label class="save-label">导出档案<textarea id="saveExport" readonly>${esc(this.profile.exportSave())}</textarea></label><button id="selectExport" class="cancel">选中导出文本，再复制保存</button><label class="save-label">导入备份<textarea id="saveImport" placeholder="粘贴之前导出的档案"></textarea></label><p id="saveFeedback" role="status"></p><button id="importArchive" class="primary wide">导入这份档案</button><button id="requestReset" class="back-link">清空长期进度…</button><button id="closeSave" class="back-link">返回基地</button>`);const $=this.$;$('selectExport').onclick=()=>{$('saveExport').focus();$('saveExport').select?.()};$('importArchive').onclick=()=>{if(this.profile.importSave($('saveImport').value)) {this.closeDialog(false);this.goBase()}else $('saveFeedback').textContent='档案格式或版本无效，当前进度未改变。'};$('closeSave').onclick=()=>this.closeDialog();$('requestReset').onclick=()=>{this.showDialog('reset',`<h2>清空长期档案？</h2><p>将清除外勤资格、遗物和线索。建议先导出备份。</p><button id="confirmReset" class="danger-button">确认清空，重新开始</button><button id="cancelReset" class="back-link">保留档案</button>`);$('confirmReset').onclick=()=>{this.profile.reset();this.closeDialog(false);this.goBase()};$('cancelReset').onclick=()=>this.openSave()}}
 renderResult(card,won){const r=this.run,out=r.missionOutcome,m=r.mission||MISSIONS.training,training=r.missionId==='training',trueEnd=out==='trueEnding',finalFail=out==='finalFailure';const title=trueEnd?'信号恢复。':finalFail?'频道仍然沉默。':won?(training?'反应完成。':'任务成功。'):(training?'实验中止。':'任务中止。');const caption=trueEnd?'威胁解除。完整结构已接入，身份识别正在恢复。':finalFail?'你停止了攻击，却没能恢复它。此前找回的记录中，或许仍有被忽略的细节。':won?(r.isEquipmentTest?'装备试验完成，不计入主线进度。':training?'装备测试通过。外勤资格已开放，你已经准备好下一次行动。':`任务已完成。${m.relic?.name||'任务记录'}已成功带回基地。`):'本次携带的物件未能带回；此前归档的遗物和发现仍然保留。';
 card.innerHTML=`<div class="campaign-outcome ${won?'mission-won':'mission-lost'} ${trueEnd?'true-ending':''}"><div class="eyebrow">${trueEnd?'CHANNEL RESTORED / 真结局':finalFail?'FINAL OPERATION FAILED / 终局失败':won?'MISSION COMPLETE / 任务成功':'MISSION FAILED / 行动中止'}</div><div class="ending-symbol">${trueEnd?'◉':won?'◇':'⌁'}</div><h2>${title}</h2><p>${caption}</p>${trueEnd?'<blockquote>“……你回来了。”</blockquote><div class="ending-lines">实验记录已恢复。<br>原始任务：核心隔离修复。<br>被侵染的记录曾将它改写为“常规回收”。<br>它按损坏的记录引导你，直到连自己的身份也无法识别。<br>你带回了材料，也带回了它。</div>':won&&!training?`<div class="extracted-relic"><span>◆</span><div><small>EXTRACTED / 成功带回</small><strong>${m.relic?.name||'任务记录'}</strong></div></div>`:''}<div class="outcome-stats"><div><b>${Math.floor(r.elapsed/60)}:${String(Math.floor(r.elapsed%60)).padStart(2,'0')}</b><small>本次用时</small></div><div><b>${r.kills}</b><small>清除目标</small></div><div><b>${r.experienceProgress.level}</b><small>角色等级</small></div></div>${won&&out!=='trueEnding'&&this.profile.keyReady?'<div class="key-notice">三件部件已组合为维护钥匙。基地出现新的访问入口。</div>':''}<div class="result-route" aria-label="任务关卡进度">${Array.from({length:10},(_,i)=>`<span class="${won||i<r.wave-1?'complete':i===r.wave-1?'failed':'future'}">${won||i<r.wave-1?'✓':String(i+1).padStart(2,'0')}</span>`).join('')}</div><div class="outcome-loadout"><small>本次装备记录</small>${r.weapons.filter(w=>w.gun).map(w=>`<strong>${weaponName(w.gun)} <span>LV.${w.gun.level} / +${w.gun.rank||0}</span></strong>`).join('')}</div><button id="back" class="primary wide">返回基地 <span>↗</span></button><button id="restart" class="back-link">${training?'再次进行装备测试':'重新执行本次任务'}</button></div>`;
 this.$('back').onclick=this.goBase;this.$('restart').onclick=()=>this.startMission(r.missionId,r.quick);
 }
}
